    for task in tasks:
        _check_task_file_paths(task, seen, violations)
    return violations


def _get_workplan(plan) -> object:
    """Extract workplan from plan or strategy, return None if neither exists."""
    workplan = getattr(plan, "workplan", None)
    if not workplan:
        strategy = getattr(plan, "strategy", None)
        if strategy:
            workplan = getattr(strategy, "parallelisable_workplan", None)
    return workplan


def _get_groups(workplan) -> list:
    """Return the groups list from a workplan, or empty list if workplan is falsy."""
    return getattr(workplan, "groups", []) if workplan else []


def _collect_tasks(groups) -> list:
    """Collect all tasks from a list of groups."""
    tasks = []
    for group in groups or []:
        tasks.extend(getattr(group, "tasks", []) or [])
    return tasks


def _check_task_file_paths(task, seen: set[str], violations: list[str]) -> None:
    """Check that a task has exactly 1 file path and no file collisions."""
    fps = getattr(task, "file_paths", None) or []
    if len(fps) != 1:
        violations.append(
            f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)"
        )
    for fp in fps:
        if fp in seen:
            violations.append(f"file collision: {fp} in multiple tasks")
        seen.add(fp)"}
